// Validación de eventos permitidos desde cliente en proxy WebSocket
const CLIENT_ALLOWED_EVENTS = new Set(["input_audio_buffer.append", "input_audio_buffer.commit"]);
ws.on("message", (raw) => {
  const evt = JSON.parse(raw);
  if (!CLIENT_ALLOWED_EVENTS.has(evt.type)) return ws.close(1008, "Forbidden event type");
});

